  [Id <String>]: Resource identity path
  [PlanName <String>]: Name of the Plan resource
  [ProtectedItemName <String>]: The protectedItem Id, name of 2 protected items can be same under a PG if they belong to different resource group or even different data source types VM/DB/AKS, etc; and name is mandatory in Azure Typespec, hence using name parameter for id in Commvault In case of Vm it will be vmGuid
  [ProtectionGroupName <String>]: Name of the ProtectionGroup resource
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [StorageName <String>]: Name of the Storage resource
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.

