$storagePlan = @{ Name = 'primary'; StoragePoolId = 'storage-hot'; CopyName = 'primary-copy'; CopyPrecedence = 1; RetentionPeriod = 30; RetentionTime = 'monthly'; BackupRuleType = 'ALL_JOBS' }
