<#
.Synopsis
Update a CommvaultPlan
.Description
Update a CommvaultPlan
.Example
Update-AzCommvaultPlan -ResourceGroupName rg-commvault -CloudAccountName cca-contoso -Name plan-daily -RetentionNumberOfSnapshot 14
.Example
$schedule = @{ BackupType = 'INCREMENTAL'; Frequency = 'daily'; RunsEvery = 1; Time = '23:30'; TimeZone = 'UTC' }
Update-AzCommvaultPlan -ResourceGroupName rg-commvault -CloudAccountName cca-contoso -Name plan-daily -Schedule $schedule

.Inputs
Microsoft.Azure.PowerShell.Cmdlets.Commvault.Models.ICommvaultIdentity
.Outputs
Microsoft.Azure.PowerShell.Cmdlets.Commvault.Models.ICommvaultPlan
.Notes
COMPLEX PARAMETER PROPERTIES

To create the parameters described below, construct a hash table containing the appropriate properties. For information on hash tables, run Get-Help about_Hash_Tables.

CLOUDACCOUNTINPUTOBJECT <ICommvaultIdentity>: Identity Parameter
  [CloudAccountName <String>]: Name of the Cloud Account resource
  [Id <String>]: Resource identity path
  [PlanName <String>]: Name of the Plan resource
  [ProtectedItemName <String>]: The protectedItem Id, name of 2 protected items can be same under a PG if they belong to different resource group or even different data source types VM/DB/AKS, etc; and name is mandatory in Azure Typespec, hence using name parameter for id in Commvault In case of Vm it will be vmGuid
  [ProtectionGroupName <String>]: Name of the ProtectionGroup resource
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [StorageName <String>]: Name of the Storage resource
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.

INPUTOBJECT <ICommvaultIdentity>: Identity Parameter
  [CloudAccountName <String>]: Name of the Cloud Account resource
  [Id <String>]: Resource identity path
  [PlanName <String>]: Name of the Plan resource
  [ProtectedItemName <String>]: The protectedItem Id, name of 2 protected items can be same under a PG if they belong to different resource group or even different data source types VM/DB/AKS, etc; and name is mandatory in Azure Typespec, hence using name parameter for id in Commvault In case of Vm it will be vmGuid
  [ProtectionGroupName <String>]: Name of the ProtectionGroup resource
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [StorageName <String>]: Name of the Storage resource
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.

SCHEDULE <ISchedule[]>: The Commvault Plan Schedule
  BackupType <String>: Type of Backup
  [DayOfMonth <Int32?>]: Day of the month
  [DayOfWeek <String>]: Day of the week
  [Frequency <String>]: Frequency of Retention
  [MonthOfYear <String>]: Month of the year
  [RunsEvery <Int32?>]: Interval of Retention
  [Time <String>]: Time of Retention
  [TimeZone <String>]: Time Zone
  [WeekOfMonth <String>]: Week of the month
  [WeeklyDay <List<String>>]: Weekly Days List
.Link
https://learn.microsoft.com/powershell/module/az.commvault/update-azcommvaultplan
#>
